<template><section class="max-w-xl space-y-5"><h1 class="text-2xl font-semibold">Change password</h1><form class="space-y-4 rounded-xl bg-background p-6 shadow" @submit.prevent="submit"><input v-model="currentPassword" type="password" required placeholder="Current password" class="w-full rounded border p-3" /><input v-model="newPassword" type="password" minlength="12" required placeholder="New password" class="w-full rounded border p-3" /><button class="rounded bg-primary px-5 py-3 text-primary-foreground">Update password</button><p>{{ message }}</p></form></section></template>
<script setup lang="ts">import { ref } from "vue"; import { useRouter } from "vue-router"; import { authHttp, clearAuth } from "@/auth"; const currentPassword = ref(""); const newPassword = ref(""); const message = ref(""); const router = useRouter(); const valid = (value: string) => value.length >= 12 && /[a-z]/.test(value) && /[A-Z]/.test(value) && /\d/.test(value) && /[^A-Za-z\d]/.test(value); const submit = async () => { if (!valid(newPassword.value)) { message.value = "Password must be 12+ characters with upper/lowercase, a number, and a symbol."; return; } try { await authHttp.post("/api/auth/password", { currentPassword: currentPassword.value, newPassword: newPassword.value }); clearAuth(); message.value = "Password updated. Please sign in again."; setTimeout(() => router.replace("/login"), 700); } catch { message.value = "Unable to update password."; } };</script>
